using System;
using System.Collections.Generic;
using System.Reflection;
using System.Text;
using RimWorld;
using UnityEngine;
using Verse;

namespace ZoologyMod
{
    // Generated by Checker from BiologicalStageMass_kg, not from game BodySize.
    public sealed class ZoologyJuvenileGraphicCatalogDef : Def
    {
        public List<ZoologyJuvenileGraphicProfile> profiles =
            new List<ZoologyJuvenileGraphicProfile>();
    }

    public sealed class ZoologyJuvenileGraphicProfile
    {
        public string animalDefName;
        public string sourceStageDefName;
        public string adultStageDefName;
        public float biologicalMass;
        public float adultMass;
        public float visualScale;
    }

    // Original PawnKind graphics are captured once, after XML patches. Every
    // configuration is constructed from that immutable source, not from a
    // previously scaled variant. No pawn comp or per-tick calculations.
    internal static class ZoologyAnimalGraphics
    {
        private static readonly MethodInfo CloneMethod = typeof(object).GetMethod(
            "MemberwiseClone", BindingFlags.Instance | BindingFlags.NonPublic);
        private static readonly MethodInfo MarkGraphicsDirty = typeof(PawnRenderer).GetMethod(
            "SetAllGraphicsDirty", BindingFlags.Public | BindingFlags.NonPublic
                | BindingFlags.Instance, null, Type.EmptyTypes, null);

        private static readonly Dictionary<ThingDef, List<ZoologyJuvenileGraphicProfile>>
            JuvenileByRace = new Dictionary<ThingDef, List<ZoologyJuvenileGraphicProfile>>();
        private static readonly Dictionary<PawnKindDef, List<PawnKindLifeStage>>
            Originals = new Dictionary<PawnKindDef, List<PawnKindLifeStage>>();
        private static readonly Dictionary<PawnKindDef, List<PawnKindLifeStage>[]>
            Variants = new Dictionary<PawnKindDef, List<PawnKindLifeStage>[]>();
        private static readonly HashSet<string> UnmatchedJuvenileStages =
            new HashSet<string>(StringComparer.Ordinal);
        private static bool reportedUnmatchedStages;
        private static bool installed;
        private static int activeMode = -1;
        internal static int GraphicVersion { get; private set; }

        internal static bool Enabled
        {
            get
            {
                var settings = ZoologyMod.Settings ?? ZoologyModSettings.Instance;
                return settings != null && !settings.DisableAllRuntimePatches
                    && settings.EnableAutomaticJuvenileSpriteScaling;
            }
        }

        internal static void Install()
        {
            if (installed)
                return;
            installed = true;
            foreach (var catalog in DefDatabase<ZoologyJuvenileGraphicCatalogDef>.AllDefsListForReading)
            {
                if (catalog?.profiles == null)
                    continue;
                foreach (var p in catalog.profiles)
                {
                    if (p == null || string.IsNullOrEmpty(p.animalDefName)
                        || string.IsNullOrEmpty(p.sourceStageDefName)
                        || string.IsNullOrEmpty(p.adultStageDefName)
                        || !(p.biologicalMass > 0f) || !(p.adultMass > p.biologicalMass)
                        || !(p.visualScale > 0f) || !(p.visualScale < 1f)
                        || float.IsNaN(p.visualScale) || float.IsInfinity(p.visualScale))
                        throw new InvalidOperationException(
                            "Invalid canonical juvenile graphics profile");
                    float check = (float)Math.Pow(p.biologicalMass / p.adultMass, 1d / 6d);
                    if (Math.Abs(check - p.visualScale) > 0.00001f)
                        throw new InvalidOperationException(
                            "Invalid juvenile graphics scale for " + p.animalDefName);
                    var race = DefDatabase<ThingDef>.GetNamedSilentFail(p.animalDefName);
                    if (race?.race?.Animal != true)
                        continue; // Optional animal pack is not loaded.
                    List<ZoologyJuvenileGraphicProfile> list;
                    if (!JuvenileByRace.TryGetValue(race, out list))
                    {
                        list = new List<ZoologyJuvenileGraphicProfile>();
                        JuvenileByRace.Add(race, list);
                    }
                    if (list.Exists(x => x.sourceStageDefName == p.sourceStageDefName))
                        throw new InvalidOperationException(
                            "Duplicate juvenile graphic stage: " + p.animalDefName
                            + "/" + p.sourceStageDefName);
                    list.Add(p);
                }
            }
            foreach (var kind in DefDatabase<PawnKindDef>.AllDefsListForReading)
            {
                if (kind?.race == null || kind.lifeStages == null)
                    continue;
                int stage;
                bool smallerFemale;
                float factor;
                if (!JuvenileByRace.ContainsKey(kind.race)
                    && !ZoologySexAdultProfiles.TryGraphicSexScale(
                        kind.race, out stage, out smallerFemale, out factor))
                    continue;
                Originals.Add(kind, kind.lifeStages);
                Variants.Add(kind, new List<PawnKindLifeStage>[4]);
            }
            Log.Message("[Zoology] Loaded juvenile sprite mass endpoints for "
                + JuvenileByRace.Count + " animal races.");
        }

        internal static void Sync(bool sexual, bool juvenile)
        {
            if (!installed)
                return;
            int mode = (sexual ? 1 : 0) | (juvenile ? 2 : 0);
            if (activeMode == mode)
                return;

            foreach (var item in Originals)
            {
                var cached = Variants[item.Key];
                if (cached[mode] == null)
                    cached[mode] = mode == 0 ? item.Value
                        : BuildVariant(item.Key, item.Value, sexual, juvenile);
                item.Key.lifeStages = cached[mode];
            }
            activeMode = mode;
            GraphicVersion++;
            ZoologyAnimalGraphicBounds.ClearCache();
            ZoologyAnimalGraphicBounds.ValidateDrawSizeOrder();
            if (juvenile && !reportedUnmatchedStages && UnmatchedJuvenileStages.Count > 0)
            {
                reportedUnmatchedStages = true;
                Log.Message("[Zoology] Skipped " + UnmatchedJuvenileStages.Count
                    + " juvenile graphic endpoints with no matching, ordered "
                    + "life-stage graphics in the installed animal mods.");
            }

            // Rebuild the render trees of animals already on loaded maps.
            // This executes on configuration changes only.
            if (Current.ProgramState == ProgramState.Playing && MarkGraphicsDirty != null)
                foreach (var map in Find.Maps)
                    foreach (var pawn in map.mapPawns.AllPawns)
                    {
                        if (pawn?.RaceProps?.Animal != true || pawn.kindDef == null
                            || !Originals.ContainsKey(pawn.kindDef))
                            continue;
                        var renderer = pawn.Drawer?.renderer;
                        if (renderer != null)
                            MarkGraphicsDirty.Invoke(renderer, null);
                    }
        }

        private static List<PawnKindLifeStage> BuildVariant(PawnKindDef kind,
            List<PawnKindLifeStage> source, bool sexual, bool juvenile)
        {
            // Each stage is cloned lazily; original GraphicData references
            // remain untouched and caches are invalidated by CopyFrom.
            var stages = new List<PawnKindLifeStage>(source);
            int adultIndex;
            bool smallerFemale;
            float smallerScale;
            if (sexual && ZoologySexAdultProfiles.TryGraphicSexScale(
                kind.race, out adultIndex, out smallerFemale, out smallerScale)
                && adultIndex >= 0 && adultIndex < stages.Count)
            {
                var adult = source[adultIndex];
                var common = adult?.bodyGraphicData;
                if (common != null && smallerScale > 0f && smallerScale < 1f)
                {
                    GraphicData authoredFemale = adult.femaleGraphicData;
                    // Only distinct female artwork retains its authored drawSize.
                    // A femaleGraphicData using the male texture is not a separate
                    // sprite: ignore its original size and apply the sex endpoint.
                    bool distinctFemaleSprite = authoredFemale != null
                        && !string.Equals(authoredFemale.texPath, common.texPath,
                            StringComparison.Ordinal);
                    if (smallerFemale)
                    {
                        if (!distinctFemaleSprite)
                        {
                            var clone = CloneStage(stages, source, adultIndex);
                            clone.femaleGraphicData = CloneGraphic(authoredFemale ?? common);
                            SetGraphicDrawSize(clone.femaleGraphicData,
                                common.drawSize * smallerScale);
                        }
                    }
                    else
                    {
                        // Even with distinct female artwork, the male sprite
                        // still needs its own smaller adult endpoint.
                        var clone = CloneStage(stages, source, adultIndex);
                        clone.bodyGraphicData = CloneGraphic(common);
                        SetGraphicDrawSize(clone.bodyGraphicData,
                            common.drawSize * smallerScale);
                        if (!distinctFemaleSprite)
                        {
                            clone.femaleGraphicData = CloneGraphic(authoredFemale ?? common);
                            SetGraphicDrawSize(clone.femaleGraphicData, common.drawSize);
                        }
                    }
                }
            }

            List<ZoologyJuvenileGraphicProfile> profiles;
            if (!juvenile || !JuvenileByRace.TryGetValue(kind.race, out profiles))
                return stages;

            foreach (var profile in profiles)
            {
                int youngIndex = ZoologySexAdultProfiles.FindStageIndex(
                    kind.race, profile.sourceStageDefName);
                int referenceIndex = ZoologySexAdultProfiles.FindStageIndex(
                    kind.race, profile.adultStageDefName);
                if (youngIndex < 0 || referenceIndex <= youngIndex
                    || referenceIndex >= source.Count || youngIndex >= source.Count)
                {
                    // The mass catalog also covers optional species whose loaded
                    // race uses different or fewer biological stages. Do not
                    // misapply an endpoint to an unrelated stage or flood the log.
                    UnmatchedJuvenileStages.Add(kind.defName + "/"
                        + profile.sourceStageDefName);
                    continue;
                }
                var adult = source[referenceIndex];
                var young = source[youngIndex];
                GraphicData anchor = adult?.bodyGraphicData;
                GraphicData body = young?.bodyGraphicData;
                if (anchor == null || body == null)
                    continue;

                var clone = CloneStage(stages, source, youngIndex);
                Vector2 commonSize = ZoologyAnimalGraphicBounds.NormalizedDrawSize(
                    anchor, body, profile.visualScale);
                clone.bodyGraphicData = CloneGraphic(body);
                SetGraphicDrawSize(clone.bodyGraphicData, commonSize);
                if (young.femaleGraphicData != null)
                {
                    GraphicData female = young.femaleGraphicData;
                    clone.femaleGraphicData = CloneGraphic(female);
                    if (female.texPath == body.texPath)
                    {
                        // An original scale-only female graphic is not sexual
                        // dimorphism in the new juvenile model.
                        SetGraphicDrawSize(clone.femaleGraphicData, commonSize);
                    }
                    else
                    {
                        // Normalize the original adult female art to the same
                        // reference body size before sizing a distinct juvenile
                        // female texture. The mature sex difference is not inherited.
                        GraphicData femaleAdult = adult.femaleGraphicData ?? anchor;
                        float correction = ZoologyAnimalGraphicBounds.AdultReferenceNormalizer(
                            anchor, femaleAdult);
                        SetGraphicDrawSize(clone.femaleGraphicData,
                            ZoologyAnimalGraphicBounds.NormalizedDrawSize(
                                femaleAdult, female, profile.visualScale * correction));
                        // Alternative juvenile textures may have different
                        // transparent margins or silhouette aspect ratios.
                        // Equalize the actual visible linear extent, not the
                        // source authors' separate female drawSize.
                        SetGraphicDrawSize(clone.femaleGraphicData,
                            ZoologyAnimalGraphicBounds.MatchVisibleLinearSize(
                                clone.bodyGraphicData, clone.femaleGraphicData));
                    }
                }
                if (young.dessicatedBodyGraphicData != null
                    && adult.dessicatedBodyGraphicData != null)
                {
                    clone.dessicatedBodyGraphicData = CloneGraphic(
                        young.dessicatedBodyGraphicData);
                    SetGraphicDrawSize(clone.dessicatedBodyGraphicData,
                        ZoologyAnimalGraphicBounds.NormalizedDrawSize(
                            adult.dessicatedBodyGraphicData,
                            young.dessicatedBodyGraphicData, profile.visualScale));
                }

                // A biological juvenile has no sex-specific size endpoint.
                // Its common size must nevertheless remain below BOTH actual
                // adult graphics, including authored female sizes or runtime
                // adult sexual dimorphism. Otherwise large near-adult juveniles
                // visibly shrink at maturation (Goose, Quail, crocodilians).
                var activeAdult = stages[referenceIndex];
                GraphicData adultMale = activeAdult?.bodyGraphicData;
                GraphicData adultFemale = activeAdult?.femaleGraphicData ?? adultMale;
                float limit = Mathf.Min(
                    ZoologyAnimalGraphicBounds.VisibleScaleLimit(
                        adultMale, clone.bodyGraphicData, profile.visualScale),
                    ZoologyAnimalGraphicBounds.VisibleScaleLimit(
                        adultFemale, clone.femaleGraphicData ?? clone.bodyGraphicData,
                        profile.visualScale));
                if (limit < 1f)
                {
                    SetGraphicDrawSize(clone.bodyGraphicData, clone.bodyGraphicData.drawSize * limit);
                    if (clone.femaleGraphicData != null)
                        SetGraphicDrawSize(clone.femaleGraphicData, clone.femaleGraphicData.drawSize * limit);
                    if (clone.dessicatedBodyGraphicData != null
                        && !ReferenceEquals(clone.dessicatedBodyGraphicData,
                            young.dessicatedBodyGraphicData))
                        SetGraphicDrawSize(clone.dessicatedBodyGraphicData,
                            clone.dessicatedBodyGraphicData.drawSize * limit);
                }
            }
            return stages;
        }

        private static PawnKindLifeStage CloneStage(List<PawnKindLifeStage> stages,
            List<PawnKindLifeStage> originals, int index)
        {
            if (ReferenceEquals(stages[index], originals[index]))
                stages[index] = (PawnKindLifeStage)CloneMethod.Invoke(originals[index], null);
            return stages[index];
        }

        private static GraphicData CloneGraphic(GraphicData source)
        {
            var copy = (GraphicData)CloneMethod.Invoke(source, null);
            copy.CopyFrom(source);
            return copy;
        }

        // GraphicData.Graphic is lazy-cached in RimWorld 1.7. Alpha-bound
        // measurements in MatchVisibleLinearSize/VisibleScaleLimit can
        // initialize it while a cloned juvenile's size is still provisional.
        // A direct drawSize assignment leaves that old Graphic.drawSize in
        // the cache, so the render mesh and daily-growth endpoint diverge.
        // GraphicData.CopyFrom explicitly clears cachedGraphic. Calling it
        // on the same instance preserves all current properties while
        // invalidating that cache after EVERY size change.
        private static void SetGraphicDrawSize(GraphicData data, Vector2 size)
        {
            data.drawSize = size;
            data.CopyFrom(data);
        }

        internal static void AppendDiagnostics(PawnKindDef kind, int index,
            bool female, StringBuilder output)
        {
            List<PawnKindLifeStage> source;
            if (kind == null || !Originals.TryGetValue(kind, out source))
                return;
            List<ZoologyJuvenileGraphicProfile> profiles;
            if (!JuvenileByRace.TryGetValue(kind.race, out profiles))
                return;
            foreach (var p in profiles)
            {
                if (ZoologySexAdultProfiles.FindStageIndex(kind.race, p.sourceStageDefName)
                    != index)
                    continue;
                int adult = ZoologySexAdultProfiles.FindStageIndex(
                    kind.race, p.adultStageDefName);
                if (adult < 0 || adult >= source.Count)
                    return;
                var refGraphic = source[adult].bodyGraphicData;
                var current = kind.lifeStages[index];
                var activeGraphic = female
                    ? current.femaleGraphicData ?? current.bodyGraphicData
                    : current.bodyGraphicData;
                if (refGraphic == null || activeGraphic == null)
                    return;
                output.Append("  Juvenile sprite: adult baseline (")
                    .Append(refGraphic.drawSize.x.ToString("0.######")).Append(", ")
                    .Append(refGraphic.drawSize.y.ToString("0.######"))
                    .Append("); biological mass ").Append(p.biologicalMass)
                    .Append(" kg; adult mass ").Append(p.adultMass)
                    .Append(" kg; scale ").Append(p.visualScale.ToString("0.########"))
                    .Append("; active drawSize (").Append(activeGraphic.drawSize.x.ToString("0.######"))
                    .Append(", ").Append(activeGraphic.drawSize.y.ToString("0.######"))
                    .Append("); texture ").Append(activeGraphic.texPath)
                    .AppendLine();
                ZoologyAnimalGraphicBounds.AppendVisibleDimensions(activeGraphic, output);
                return;
            }
        }
    }
}
